dashboard.definition:
{
    "title": "Medizintechnik und IoT",
    "description": "Medizingeraete: Verbindung, Status und Alarme je Geraeteklasse, Helium und Temperaturen der MRT, STK/MTK aus dem Asset Management",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Haus",
            "options": {
                "items": [
                    {
                        "label": "Alle Haeuser",
                        "value": "*"
                    },
                    {
                        "label": "Haus A - Innere Medizin",
                        "value": "A"
                    },
                    {
                        "label": "Haus B - Chirurgisches Zentrum",
                        "value": "B"
                    },
                    {
                        "label": "Haus C - Akut- und Intensivzentrum",
                        "value": "C"
                    },
                    {
                        "label": "Haus D - Frauen, Kind und Psyche",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "device": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_latest": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:medtech:telemetry\" department=\"$dept$\" building=\"$building$\" earliest=-20m\n| stats latest(device_class) as device_class latest(device_type) as device_type latest(manufacturer) as manufacturer latest(model) as model latest(status) as status latest(connectivity) as connectivity latest(alarm_count) as alarms latest(ward) as ward latest(building) as building latest(department) as department by device_id",
                "enableSmartSources": true
            },
            "name": "Geraetestatus"
        },
        "ds_k_total": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count as Geraete"
            }
        },
        "ds_k_online": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count(eval(connectivity=\"online\")) as on count as n | eval \"Online %\"=round(100 * on / n, 1) | fields \"Online %\""
            }
        },
        "ds_k_offline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where connectivity!=\"online\" | stats count as Offline"
            }
        },
        "ds_k_alarms": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats sum(alarms) as \"Aktive Alarme\""
            }
        },
        "ds_k_he": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.mri.helium_level_pct\" device_id=\"MRT-1\" span=5m | rename v as \"MRT-1 Helium\"",
                "enableSmartSources": true
            }
        },
        "ds_k_stk": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:alm_asset\" model_category=\"Medizintechnik\" earliest=-7h | stats latest(u_stk_days_left) as d by asset_tag | where d<0 | stats count as \"STK ueberfaellig\"",
                "enableSmartSources": true
            }
        },
        "ds_imaging": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:medtech:telemetry\" device_type IN (\"MRT\", \"CT\") earliest=-10m\n| stats latest(device_type) as device_type latest(manufacturer) as manufacturer latest(model) as model latest(status) as status latest(helium_level_pct) as helium_level_pct latest(magnet_temp_k) as magnet_temp_k latest(shield_temp_k) as shield_temp_k latest(cold_head_status) as cold_head_status latest(tube_heat_pct) as tube_heat_pct latest(exams_today) as exams_today latest(scans_today) as scans_today by device_id\n| eval exams_today=coalesce(exams_today, scans_today)",
                "enableSmartSources": true
            },
            "name": "Grossgeraete"
        },
        "ds_he": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.mri.helium_level_pct\" BY device_id span=5m\n| timechart span=5m avg(v) by device_id",
                "enableSmartSources": true
            },
            "name": "Heliumstand MRT"
        },
        "ds_shield": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.mri.shield_temp_k\", \"sakh.mri.compressor_water_temp_c\") device_id=\"$device$\" BY metric_name device_id span=5m\n| eval series=device_id.\" \".if(metric_name=\"sakh.mri.shield_temp_k\", \"Schild K\", \"Kuehlwasser °C\") | timechart span=5m avg(v) by series",
                "enableSmartSources": true
            }
        },
        "ds_class": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| eval state=if(connectivity!=\"online\", \"Offline\", if(alarms>0, \"Alarm\", status))\n| chart count over device_class by state"
            }
        },
        "ds_online_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.medtech.online\" department=\"$dept$\" building=\"$building$\" BY building span=10m\n| eval v=round(100 * v, 1), building=\"Haus \".building | timechart span=10m avg(v) by building",
                "enableSmartSources": true
            }
        },
        "ds_offline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where connectivity!=\"online\" OR alarms>0\n| table device_id device_class manufacturer model building ward status connectivity alarms\n| rename device_id as Geraet device_class as Klasse manufacturer as Hersteller model as Modell building as Haus ward as Station status as Status connectivity as Verbindung alarms as Alarme"
            }
        },
        "ds_stk": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:alm_asset\" model_category=\"Medizintechnik\" u_department=\"$dept$\" earliest=-7h\n| stats latest(display_name) as Geraet latest(model) as Modell latest(manufacturer) as Hersteller latest(u_stk_due) as \"STK faellig\" latest(u_stk_days_left) as \"Tage\" latest(u_mtk_due) as \"MTK faellig\" latest(u_stk_status) as Status latest(u_department) as Abteilung by asset_tag\n| where Tage < 45 | sort Tage | fields - asset_tag",
                "enableSmartSources": true
            }
        },
        "ds_alarm_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.medtech.alarm_count\" department=\"$dept$\" building=\"$building$\" BY device_type span=15m\n| timechart span=15m sum(v) by device_type",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_diag": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_diag.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_lab",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_medtech": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_medtech_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_nav_network": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_network.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_network",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_it": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_it.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_servers",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_security": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_security.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_security",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_total"
            },
            "options": {
                "majorColor": "#60a5fa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_online"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 90,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 90,
                        "to": 98,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 98,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_offline"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 10,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 10,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_alarms"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 5,
                        "to": 15,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 15,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_he"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 70,
                        "to": 80,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 80,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_stk"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 5,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 5,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "kis_studio.imaging_status",
            "dataSources": {
                "primary": "ds_imaging"
            },
            "options": {
                "drilldownToken": "device"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "device",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_he"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "yAxisMin": 50,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_shield"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_class"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#22d3ee",
                    "#a78bfa",
                    "#60a5fa"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_11": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_online_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "yAxisMin": 0,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_12": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_alarm_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_13": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_offline"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Status": {
                        "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(statusBg)"
                    },
                    "Verbindung": {
                        "rowBackgroundColors": "> table | seriesByName(\"Verbindung\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    },
                    {
                        "match": "kritisch",
                        "value": "#5a1426"
                    },
                    {
                        "match": "voll",
                        "value": "#5a1426"
                    },
                    {
                        "match": "gestoppt",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Gesperrt",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Offline",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Fehler",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Vulnerable",
                        "value": "#5a1426"
                    },
                    {
                        "match": "ueberfaellig",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Rettungsstopp",
                        "value": "#5a1426"
                    },
                    {
                        "match": "unterbesetzt",
                        "value": "#5a1426"
                    },
